			/**
			 * 5학년이상 유무 판단
			 * @param
			 */
			function getGrade() {

			    var trprBrthYear = "";
			    //오늘날짜 설정
			    var toYear = moment().format("YYYY");

			    //대상자기본정보  생년월일
			    app.getHostAppInstance().getAllDataControls().forEach(function(ctrl) {
			        if(ctrl.type == "dataset") {
			            if(ctrl.id == "dsDetailInfo") {
			                trprBrthYear  = ctrl.getValue(0, "TRPR_BRTH_YMD").substring(0, 4);
			            }
			        }
			    });

			    var agea = ValueUtil.fixNumber(toYear) - ValueUtil.fixNumber(trprBrthYear) + 1; //년나이

			    if (agea >= 14) {
			        gSchlSeCd = "2";
			    } else {
			        gSchlSeCd = "1";
			    }

			    if (agea >= 12) { //5학년이상
			        return "2";
			    }  else {
			        return "1";
			    }
			}

			/**
			 * 대상자기본정보 가져오기
			 * @param
			 */
			function getTrprInfoNo() {

			    var trprInfoNo = "";
			    //오늘날짜 설정
			    var toYear = moment().format("YYYY");

			    //대상자기본정보  생년월일
			    app.getHostAppInstance().getAllDataControls().forEach(function(ctrl) {
			        if(ctrl.type == "dataset") {
			            if(ctrl.id == "dsDetailInfo") {
			                trprInfoNo  = ctrl.getValue(0, "TRPR_INFO_NO");
			            }
			        }
			    });

			    return trprInfoNo;
			}

