			        qustnbTmptMngNo1 = dsQustnbKnd.getValue(0, "ADDTNG_MNG_VALUE1");
			        qustnbTmptMngNo2 = dsQustnbKnd.getValue(0, "ADDTNG_MNG_VALUE2");
