			function setVisibleClinicControl(poType) {
				if ("0" == poType) {
					util.Tab.setVisibleTabItem(app, "tabContents", 4, false);
				} else {
					var dsCnctrClinic = app.lookup("dsCnctrClinic");
					var dmCnctrClinicInfo = app.lookup("dmCnctrClinicInfo");

					// 사전 사후 여부 01 사전, 02 사후 03 추후
					dmCnctrClinicInfo.setValue("CASE_MNG_NO", caseMngNo);
					dmCnctrClinicInfo.setValue("CASE_MNG_ODRNO",caseMngOdrno);
					dmCnctrClinicInfo.setValue("BEFFAT_AFTFCT_SE_CD", "01");
					dmCnctrClinicInfo.setValue("CLINIC_INSP_SE_CD", poType);


					// alert(app.lookup("dmListParam").getValue("CASE_MNG_NO"));
					clinicYn = true;
					util.Tab.setVisibleTabItem(app, "tabContents", 4, true);

					if ("1" == poType) {
						//TM2023083000001
						util.Control.setVisible(app, true, ["grpSucCont"]);  // 자살
						util.Control.setVisible(app, false, ["grpInjCont"]); // 비자살적 자해
					} else if ("2" == poType) {
						//TM2023083000002
						util.Control.setVisible(app, false, ["grpSucCont"]); // 자살
						util.Control.setVisible(app, true, ["grpInjCont"]);  // 비자살적 자해
					} else if ("3" == poType) {
						// 둘다.
						util.Control.setVisible(app, true, ["grpSucCont"]);  // 자살
						util.Control.setVisible(app, true, ["grpInjCont"]);  // 비자살적 자해
					}


					// 여기서 부터 다시 하면 됨.
					util.Submit.send(app, "subCnctrClinic", function(pbSuccess) {
				        if (pbSuccess) {
				        	var dsCnctrClinicSrvy = app.lookup("dsCnctrClinicSrvy");

							if (dsCnctrClinic.getRowCount() == 0) {
								dsCnctrClinic.addRow();
								dsCnctrClinic.setValue(0, "CASE_MNG_NO", caseMngNo);
								dsCnctrClinic.setValue(0, "CASE_MNG_ODRNO", caseMngOdrno);
								dsCnctrClinic.setValue(0, "BEFFAT_AFTFCT_SE_CD", "01");
							}
							var dsCnctrSucClinic = app.lookup("dsCnctrSucClinic");
							var dsCnctrInjClinic = app.lookup("dsCnctrInjClinic");
							var sucCnt = ValueUtil.fixNumber(0);
							var injCnt1 = ValueUtil.fixNumber(0);
							var injCnt2 = ValueUtil.fixNumber(0);
							for (var i=0;i<dsCnctrSucClinic.getRowCount();i++) {
								var rspnsValue = dsCnctrSucClinic.getValue(i, "QESITM_SINGL_RSPNS_VALUE");

								sucCnt += ValueUtil.fixNumber(rspnsValue);
							}
							var ipb25 = app.lookup("ipb25");
							ipb25.value = sucCnt;

							for (var i=0;i<dsCnctrInjClinic.getRowCount();i++) {
								var rspnsValue = dsCnctrInjClinic.getValue(i, "QESITM_SINGL_RSPNS_VALUE");

								if (i <= 11) {
									injCnt1 += ValueUtil.fixNumber(rspnsValue);
			                    }
			                    if (11 < i ) {
									injCnt2 += ValueUtil.fixNumber(rspnsValue);
			                    }
								// sucCnt += ValueUtil.fixNumber(rspnsValue);
							}


							var ipb24 = app.lookup("ipb24");
							var ipb26 = app.lookup("ipb26");

							ipb24.value = injCnt1;
							ipb26.value = injCnt2;

			                util.Control.redraw(app, "grpInjCont");

				        }
				    });
				}

				util.Control.redraw(app, "grp6");

			}

